<section class="settings-group"><x-section-heading tag="h3" icon="users" tone="warning">Session policy</x-section-heading><x-setting-select name="idle_minutes" label="Idle session timeout" :value="$values['idle_minutes']" :options="[5=>'5 minutes',10=>'10 minutes',15=>'15 minutes',30=>'30 minutes',60=>'60 minutes']" /><x-setting-select name="absolute_hours" label="Maximum session duration" :value="$values['absolute_hours']" :options="[1=>'1 hour',2=>'2 hours',4=>'4 hours',8=>'8 hours',12=>'12 hours']" /><x-input id="failed-attempts" name="values[failed_attempts]" type="number" label="Failed sign-in attempts before cooldown" :value="$values['failed_attempts']" min="3" max="5" required /><x-input id="cooldown-minutes" name="values[cooldown_minutes]" type="number" label="Sign-in cooldown · minutes" :value="$values['cooldown_minutes']" min="15" max="60" required /><x-input id="password-minimum" name="values[password_min]" type="number" label="Minimum passphrase length" :value="$values['password_min']" min="15" max="128" required /></section><section class="settings-group"><x-section-heading tag="h3" icon="users" tone="warning">Required controls</x-section-heading><x-setting-value label="Account access" value="Individual active accounts · fixed roles" /><x-setting-value label="Protected actions" value="Current Manager verification" /><x-setting-value label="Recovery" value="Private, short-lived, one-use local codes" /><x-setting-value label="Activity recording" value="Always enabled" /><p>Saved session limits apply to subsequent requests. Existing passphrases remain usable until their next change; all new passphrases follow the saved minimum.</p><noscript><x-input id="manager-password-fallback" name="manager_password" type="password" label="Your Manager passphrase" required /></noscript></section>
